actions.action:
// Economic nexus established per Wayfair - filing required
// DC has relatively low thresholds for economic nexus
// Apportionment will be calculated by tables 7000-7500

// No nexus - no filing required
apportionment.state_tax = 0.0;
result.dc_minimum_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate DC state additions
            double additions = 0.0;

            // DC requires addback of federal interest income
            // (U.S. government obligations are not taxable federally but may be to DC)
            // additions += revenue.federal_bond_interest;

            // DC requires addback of IRC 199A deduction if claimed on federal return
            // (DC decouples from IRC 199A)
            // additions += result.section_199a_deduction;

            // DC requires addback of bonus depreciation
            // (DC decouples from federal bonus depreciation provisions)
            // additions += result.bonus_depreciation_total;

            // DC requires addback of state income taxes deducted on federal return
            // additions += result.state_income_tax_deduction;

            apportionment.state_additions = additions;

            // Calculate DC state subtractions
            double subtractions = 0.0;

            // Subtract DC municipal bond interest
            // (exempt from DC tax but may have been included in federal income)
            // subtractions += revenue.dc_municipal_interest;

            // Subtract qualified QHTC income deductions
            // (DC offers special deductions for qualified high technology companies)
            // subtractions += result.dc_qhtc_deduction;

            // Subtract DC NOL carryforward
            // (DC has different NOL rules than federal - 5-year carryforward)
            // subtractions += result.dc_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // DC uses 8.25% flat rate
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract DC state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Note: Minimum tax comparison happens in table 55090
            // DC tax is the GREATER of income-based tax or minimum tax

// No income-based tax, but minimum tax still applies
// Minimum tax calculation happens in table 55090
apportionment.state_tax = 0.0;

            // Minimum tax: $1,000 for gross receipts > $1M
            result.dc_minimum_tax = 1000.0;

            // DC franchise tax is GREATER of income-based tax or minimum tax
            apportionment.state_tax = Math.max(apportionment.state_tax, result.dc_minimum_tax);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // Minimum tax: $250 for gross receipts <= $1M
            result.dc_minimum_tax = 250.0;

            // DC franchise tax is GREATER of income-based tax or minimum tax
            apportionment.state_tax = Math.max(apportionment.state_tax, result.dc_minimum_tax);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

result.dc_minimum_tax = 0.0;
// state_tax already set to 0.0 in table 55080
apportionment.state_refund_or_owed = apportionment.state_payments;
